const float PI = 3.14159265359;
// const vec3 FLAG_BLUE = vec3(0.0, 0.1294, 0.2784);
// const vec3 FLAG_RED = vec3(0.7333, 0.0745, 0.2431);
const vec3 FLAG_RED = vec3(0.698, 0.132, 0.203);
const vec3 FLAG_BLUE = vec3(0.234, 0.233, 0.430);
const vec3 FLAG_WHITE = vec3(1.0, 1.0, 1.0);
const float FLAG_ASPECT_RATIO = 1.0 / 1.9;
const float FLAG_UNION_W = 4.0 / 10.0;
const float FLAT_UNION_H = 7.0 / 13.0;
const float ANIMATION_DURATION = 6.0;

float stripes(vec2 uv, float aspect) {
    uv.x *= aspect * 2.0;

    // move origin to center of union
    float offset_x = FLAG_UNION_W * aspect;
    float offset_y = 1.0 - float(FLAT_UNION_H) / 2.0;

    float circle_radius = smoothstep(0.0, 1.0, abs(mod(iTime / ANIMATION_DURATION, 2.0) - 1.0)) * 13.0 + 2.0;

    float x = uv.x - offset_x;
    float y = uv.y - offset_y;

    float alpha = (x * x + y * y) / (2.0 * y);
    alpha = 1.0 / alpha * circle_radius;
    int idx = int(alpha);
    int n13 = int(mod(float(idx + 2), 13.0));

    if (mod(float(n13), 2.0) == 0.0) {
        return 1.0;
    }
    return 0.0;
}

float stripesSupersampled16x(vec2 uv, float aspect) {
    float sum = 0.0;
    float stepX = 0.25 / iResolution.x;
    float stepY = 0.25 / iResolution.y;

    for (int i = 0; i < 4; i++) {
        for (int j = 0; j < 4; j++) {
            vec2 offset = vec2(
                (float(i) + 0.5) * stepX,
                (float(j) + 0.5) * stepY
            );
            sum += stripes(uv + offset, aspect);
        }
    }
    return sum / 16.0;
}

