// Signed distance to a regular 5-sided start.
float sdfStar(in vec2 p, in float r, in float rf)
{
    const vec2 k1 = vec2(0.809016994375, -0.587785252292);
    const vec2 k2 = vec2(-k1.x, k1.y);

    // repeat domain 5x
    p.x = abs(p.x);
    p -= 2.0 * max(dot(k1, p), 0.0) * k1;
    p -= 2.0 * max(dot(k2, p), 0.0) * k2;
    p.x = abs(p.x);

    // draw triangle
    p.y -= r;
    vec2 ba = rf * vec2(-k1.y, k1.x) - vec2(0, 1);
	float h = clamp(dot(p, ba) / dot(ba, ba), 0.0, r);
    return length(p - ba * h) * sign(p.y * ba.x - p.x * ba.y);
}

float starCircle(vec2 uv, float baseStarRadius, float circleRadius)
{
    float starInnerRadius = 0.382;
    float falloffMultiplier = 1.09;
    float minDistance = 1e6;
    int numStars = 50;

    for (int i = 0; i < numStars; i++)
    {
        float starRadius = baseStarRadius * (1.0 - falloffMultiplier * sin(PI * float(i) / float(numStars)));

        float normalizedI = float(i) / float(numStars);
        float angle = 2.0 * PI * (normalizedI + 0.15 * sin(2.0 * PI * normalizedI));
        vec2 starPos = vec2(cos(angle), sin(angle)) * circleRadius;
        float d = sdfStar(uv - starPos, starRadius, starInnerRadius);
        minDistance = min(minDistance, d);
    }

    // anti-aliasing
    float epsilon = 0.005;
    return 1.0 - smoothstep(-epsilon, epsilon, minDistance);
}

float rightSideUnion(vec2 uv, float circleRadius)
{
    int numConcentric = 40;
    float baseStarRadius = 0.1 * circleRadius;
    float ratio = 0.8;
    float totalRadiusSum = circleRadius * (1.0 - pow(ratio, float(numConcentric))) / (1.0 - ratio);

    float color = 0.0;
    for (int i = 0; i < numConcentric; i++) {
        color += starCircle(uv, baseStarRadius, circleRadius);
        circleRadius *= ratio;
        baseStarRadius *= ratio;
        uv.x += circleRadius / 4.0;
    }
    return color;
}

float flagUnion(vec2 uv)
{
    // mirror and offset
    uv.x = abs(uv.x);
    float circleRadius = smoothstep(0.0, 1.0, abs(mod(iTime / ANIMATION_DURATION, 2.0) - 1.0)) * 13.0 * 2.0 + 2.0;
    uv.x -= circleRadius;
    return rightSideUnion(uv, circleRadius);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
	vec2 coord = fragCoord / iResolution.xy - 0.5;

	float aspect = FLAG_ASPECT_RATIO * (iResolution.x / iResolution.y);
	coord.x *= max(aspect, 1.0);
	coord.y /= min(aspect, 1.0);
	coord += 0.5;
	float stencil = 1.0 - step(1.0e-6, distance(coord, fract(coord)));

    vec3 color = vec3(0.0);
    bool in_union = coord.x < float(FLAG_UNION_W) && coord.y > (1.0 - float(FLAT_UNION_H));
    if (in_union) {
        coord = (2.0 * coord - vec2(FLAG_UNION_W, 2.0 * (1.0 - FLAT_UNION_H))) 
              * vec2(1.0 / (FLAG_UNION_W * aspect), 1.0 / FLAT_UNION_H);
        coord.y -= 1.0;
        color = mix(FLAG_BLUE, vec3(1.0), flagUnion(coord));
    } else {
        float stripe = stripesSupersampled16x(coord, aspect);
        color = mix(FLAG_WHITE, FLAG_RED, stripe);
    }
	fragColor = stencil * vec4(color, 1.0);
}
